    template<class Trule>
    class da_ac_automaton : public ac_automaton_interface<Trule> {
        public:
            using pattern_data = typename ac_automaton_interface<Trule>::pattern_data;
            using pattern_hit_callback = typename ac_automaton_interface<Trule>::pattern_hit_callback;

        public:
            da_ac_automaton() = default;
            ~da_ac_automaton() override = default;

            bool compile(const std::vector<pattern_data>& patterns, bool case_insensitive = true) override {
                this->clear();

                // Build byte-folding map (identity map, with ASCII A-Z folded to a-z when case-insensitive).
                for (int i = 0; i < 256; i++)
                {
                    this->_byte_map[i] = static_cast<uint8_t>(i);
                }
                if (case_insensitive)
                {
                    for (int i = 'A'; i <= 'Z'; i++)
                    {
                        this->_byte_map[i] = static_cast<uint8_t>(i - 'A' + 'a');
                    }
                }

                // Build a temporary trie over folded raw bytes (0x00 ~ 0xFF).

                // clang-format off
                struct node {
                    std::vector<std::pair<uint8_t, std::size_t>> children; // (folded byte, child node index in trie)
                    std::vector<hit_entry> own_hits;                       // rules terminating directly at this trie node
                }; // struct node
                // clang-format on

                std::vector<node> trie(1); // node 0 is the root
                bool has_pattern = false;
                for (const auto& it_pattern : patterns)
                {
                    if (it_pattern.pattern.empty())
                    {
                        continue;
                    } // skip empty pattern
                    has_pattern = true;

                    std::size_t current_node = 0; // start from root
                    for (unsigned char it_raw_c : it_pattern.pattern)
                    {
                        const uint8_t byte_val = this->_byte_map[it_raw_c];
                        std::size_t next_node = 0;
                        for (const auto& [it_edge_byte, it_child_id] : trie[current_node].children)
                        {
                            if (it_edge_byte == byte_val)
                            {
                                next_node = it_child_id;
                                break;
                            } // existing child edge found for this byte
                        }
                        if (next_node == 0)
                        {
                            next_node = trie.size();
                            trie.emplace_back();
                            trie[current_node].children.emplace_back(byte_val, next_node);
                        } // no edge for this byte yet; append a new child node
                        current_node = next_node;
                    }

                    hit_entry hit = { it_pattern.hit_rule, static_cast<uint32_t>(it_pattern.pattern.size()) };
                    trie[current_node].own_hits.push_back(hit);
                }

                if (!has_pattern)
                {
                    this->clear();
                    return false;
                } // no non-empty patterns provided

                const std::size_t n_nodes = trie.size();

                // Prepare doubly-linked free list to find compact base offsets in O(1) amortized time.
                // Slot 0 is permanently reserved for the root state.
                constexpr uint32_t free_none = EMPTY_CHECK;
                std::vector<uint8_t> is_used;
                std::vector<uint32_t> free_prev;
                std::vector<uint32_t> free_next;
                uint32_t free_head = free_none;
                uint32_t free_tail = free_none;

                auto ensure_size = [&](std::size_t target_size) {
                    const std::size_t old_size = this->_units.size();
                    if (target_size <= old_size)
                    {
                        return;
                    }
                    this->_units.resize(target_size);
                    is_used.resize(target_size, 0);
                    free_prev.resize(target_size, free_none);
                    free_next.resize(target_size, free_none);

                    for (std::size_t s = old_size; s < target_size; s++)
                    {
                        const uint32_t slot = static_cast<uint32_t>(s);
                        if (free_tail == free_none)
                        {
                            free_head = slot;
                            free_tail = slot;
                        }
                        else
                        {
                            free_next[free_tail] = slot;
                            free_prev[slot] = free_tail;
                            free_tail = slot;
                        }
                    }
                };

                auto mark_used = [&](uint32_t slot) {
                    is_used[slot] = 1;
                    const uint32_t prev = free_prev[slot];
                    const uint32_t next = free_next[slot];
                    if (prev != free_none)
                    {
                        free_next[prev] = next;
                    }
                    else
                    {
                        free_head = next;
                    }
                    if (next != free_none)
                    {
                        free_prev[next] = prev;
                    }
                    else
                    {
                        free_tail = prev;
                    }
                    free_prev[slot] = free_none;
                    free_next[slot] = free_none;
                };

                auto find_base = [&](const std::vector<std::pair<uint8_t, std::size_t>>& children) -> std::size_t {
                    const uint32_t first_byte = children.front().first;
                    uint32_t cur = free_head;
                    uint32_t trials = 0;

                    while (cur != free_none)
                    {
                        // Ensure base = cur - first_byte >= 1 so slot 0 (root) is never overwritten.
                        if (cur >= first_byte + 1)
                        {
                            const std::size_t candidate_base = static_cast<std::size_t>(cur) - first_byte;
                            bool fits = true;
                            for (std::size_t j = 1; j < children.size(); j++)
                            {
                                const std::size_t slot = candidate_base + children[j].first;
                                if (slot < is_used.size() && is_used[slot] != 0)
                                {
                                    fits = false;
                                    break;
                                }
                            }
                            if (fits)
                            {
                                return candidate_base;
                            }
                            trials++;
                            if (trials >= MAX_FIND_TRIALS)
                            {
                                break;
                            } // stop scanning crowded prefix and place at tail
                        }
                        cur = free_next[cur];
                    }

                    // Tail placement: guaranteed free for all bytes in [0, 255].
                    return std::max<std::size_t>(this->_units.size(), 1);
                };

                // Initialize slot 0 as root (check stays EMPTY_CHECK so only real children have check == 0).
                ensure_size(256);
                mark_used(0);

                // Place trie nodes into _units in BFS order (keeps shallow/hot states at the front for cache locality)
                // and compute failure links in the same BFS pass.
                std::vector<std::size_t> bfs_order;
                bfs_order.reserve(n_nodes);
                std::vector<uint32_t> trie_to_da(n_nodes, 0);

                std::queue<std::size_t> q;
                q.push(0);
                bfs_order.push_back(0);
                trie_to_da[0] = 0;

                std::size_t max_base = 0;

                while (!q.empty())
                {
                    const std::size_t trie_u = q.front();
                    q.pop();

                    auto& children = trie[trie_u].children;
                    const uint32_t da_u = trie_to_da[trie_u];

                    if (children.empty())
                    {
                        // Leaf state: base = 0 is safe because no slot has check == da_u.
                        this->_units[da_u].base = 0;
                        continue;
                    }

                    std::sort(children.begin(), children.end(),
                              [](const auto& a, const auto& b) { return a.first < b.first; });

                    const std::size_t base = find_base(children);
                    if (base + 256 >= static_cast<std::size_t>(EMPTY_CHECK))
                    {
                        this->clear();
                        return false;
                    } // slot index would overflow uint32_t

                    const std::size_t max_child_slot = base + children.back().first;
                    ensure_size(max_child_slot + 1);

                    this->_units[da_u].base = static_cast<uint32_t>(base);
                    if (base > max_base)
                    {
                        max_base = base;
                    }

                    for (const auto& [it_byte, it_child_trie] : children)
                    {
                        const uint32_t da_child = static_cast<uint32_t>(base + it_byte);
                        mark_used(da_child);
                        this->_units[da_child].check = da_u;
                        trie_to_da[it_child_trie] = da_child;

                        // Compute failure state for da_child.
                        // All strictly shallower states already have their base and fail finalized (BFS order).
                        if (da_u == 0)
                        {
                            this->_units[da_child].fail = 0;
                        }
                        else
                        {
                            uint32_t fail_state = this->_units[da_u].fail;
                            while (true)
                            {
                                const std::size_t next_slot =
                                    static_cast<std::size_t>(this->_units[fail_state].base) + it_byte;
                                if (next_slot < this->_units.size() && this->_units[next_slot].check == fail_state)
                                {
                                    this->_units[da_child].fail = static_cast<uint32_t>(next_slot);
                                    break;
                                }
                                if (fail_state == 0)
                                {
                                    this->_units[da_child].fail = 0;
                                    break;
                                }
                                fail_state = this->_units[fail_state].fail;
                            }
                        }

                        bfs_order.push_back(it_child_trie);
                        q.push(it_child_trie);
                    }
                }

                // Pad _units to max_base + 256 so match() can index units[base + c] with zero bounds checks.
                ensure_size(max_base + 256);

                // Pre-count total flattened hits in BFS order and reserve _hits once to avoid O(M^2) reallocation.
                std::vector<uint32_t> slot_hit_counts(this->_units.size(), 0);
                std::size_t total_hits = 0;
                std::size_t n_hit_states = 0;
                for (std::size_t trie_id : bfs_order)
                {
                    const uint32_t da_u = trie_to_da[trie_id];
                    uint32_t count = static_cast<uint32_t>(trie[trie_id].own_hits.size());
                    if (da_u != 0)
                    {
                        count += slot_hit_counts[this->_units[da_u].fail];
                    }
                    slot_hit_counts[da_u] = count;
                    total_hits += count;
                    if (count > 0)
                    {
                        n_hit_states++;
                    }
                }

                this->_hits.reserve(total_hits);
                this->_hit_slices.reserve(n_hit_states);

                // Flatten hits per state (own hits + inherited suffix hits via fail links) in BFS order.
                for (std::size_t trie_id : bfs_order)
                {
                    const uint32_t da_u = trie_to_da[trie_id];
                    if (slot_hit_counts[da_u] == 0)
                    {
                        continue;
                    }

                    const uint32_t offset = static_cast<uint32_t>(this->_hits.size());
                    const auto& own = trie[trie_id].own_hits;
                    this->_hits.insert(this->_hits.end(), own.begin(), own.end());

                    if (da_u != 0)
                    {
                        const uint32_t fail_hit_idx = this->_units[this->_units[da_u].fail].hit_idx;
                        if (fail_hit_idx != NO_HIT)
                        {
                            const auto fail_slice = this->_hit_slices[fail_hit_idx];
                            for (uint32_t i = 0; i < fail_slice.count; i++)
                            {
                                this->_hits.push_back(this->_hits[fail_slice.offset + i]);
                            }
                        }
                    }

                    const uint32_t count = static_cast<uint32_t>(this->_hits.size()) - offset;
                    this->_units[da_u].hit_idx = static_cast<uint32_t>(this->_hit_slices.size());
                    this->_hit_slices.push_back({ offset, count });
                }

                return true;
            }

            void match(std::string_view text, pattern_hit_callback hit_cb, void* user_data = nullptr) const override {
                if (this->_units.empty() || !hit_cb)
                {
                    return;
                } // automaton not compiled or null callback

                const auto* text_data = reinterpret_cast<const uint8_t*>(text.data());
                const std::size_t text_len = text.size();
                const state_unit* units = this->_units.data();

                uint32_t current_state = 0;
                for (std::size_t i = 0; i < text_len; i++)
                {
                    const uint8_t byte_val = this->_byte_map[text_data[i]];

                    // Hot path: single-array lookup with fail fallback (padded _units guarantees in-bounds access).
                    while (true)
                    {
                        const uint32_t next_state = units[current_state].base + byte_val;
                        if (units[next_state].check == current_state)
                        {
                            current_state = next_state;
                            break;
                        }
                        if (current_state == 0)
                        {
                            break;
                        }
                        current_state = units[current_state].fail;
                    }

                    // Cold path: emit all flattened hits when current_state has hits.
                    const uint32_t hit_idx = units[current_state].hit_idx;
                    if (hit_idx != NO_HIT)
                    {
                        const auto& slice = this->_hit_slices[hit_idx];
                        for (uint32_t j = 0; j < slice.count; j++)
                        {
                            const auto& it_hit = this->_hits[slice.offset + j];
                            // Half-open byte range [begin_pos, end_pos) in text
                            const std::size_t begin_pos = i + 1 - it_hit.pattern_len;
                            const std::size_t end_pos = i + 1;
                            hit_cb(it_hit.rule, begin_pos, end_pos, user_data);
                        }
                    }
                }
                return;
            }

            void clear() noexcept override {
                for (uint8_t& it_b : this->_byte_map)
                {
                    it_b = 0;
                }
                this->_units.clear();
                this->_hit_slices.clear();
                this->_hits.clear();
                return;
            }

        private:
            static constexpr uint32_t EMPTY_CHECK = ~uint32_t(0);
            static constexpr uint32_t NO_HIT = ~uint32_t(0);
            static constexpr uint32_t MAX_FIND_TRIALS = 32;

            // clang-format off

            // 16-byte aligned state unit (4 units per 64-byte cache line) so base/check/fail/hit_idx share one load.
            struct state_unit {
                uint32_t base = 0;             // base offset for child transitions (0 for leaf states)
                uint32_t check = EMPTY_CHECK;  // parent state ID (EMPTY_CHECK if slot is unused or root)
                uint32_t fail = 0;             // failure state ID in _units
                uint32_t hit_idx = NO_HIT;     // index into _hit_slices, or NO_HIT if no hits at this state
            }; // struct state_unit

            struct hit_slice {
                uint32_t offset = 0; // start index in _hits
                uint32_t count = 0;  // number of flattened hits for this state
            }; // struct hit_slice

            struct hit_entry {
                Trule rule;
                uint32_t pattern_len; // matched pattern length in bytes
            }; // struct hit_entry

            // clang-format on

            // Hot data: accessed on every input byte during match()
            uint8_t _byte_map[256] = {};    // raw byte -> folded byte (identity or ASCII lowercase)
            std::vector<state_unit> _units; // double-array state pool (padded by 256 sentinel slots)

            // Cold data: accessed only when units[state].hit_idx != NO_HIT
            std::vector<hit_slice> _hit_slices; // slices for hit states only
            std::vector<hit_entry> _hits;       // contiguous pool of all flattened pattern hits

    }; // class da_ac_automaton

